package com.easyperformance.program;
import com.easyperformance.program.ProgramTypes.ProgramEventType;import com.easyware.platform.UuidV7;import com.easyware.platform.audit.TenantAwareAuditEntity;import jakarta.persistence.*;import org.hibernate.annotations.Immutable;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.util.UUID;
@Entity @Immutable @Table(name="program_audit_event",indexes={@Index(name="ix_program_audit_tenant_program",columnList="tenant_id, program_id, created_at"),@Index(name="ix_program_audit_tenant_participant",columnList="tenant_id, participant_id, created_at")})
public class ProgramAuditEvent extends TenantAwareAuditEntity{
 @Id@Column(columnDefinition="uuid",nullable=false,updatable=false)private UUID id;@Column(name="program_id",columnDefinition="uuid",nullable=false,updatable=false)private UUID programId;@Column(name="participant_id",columnDefinition="uuid",updatable=false)private UUID participantId;@Enumerated(EnumType.STRING)@Column(name="event_type",nullable=false,length=40,updatable=false)private ProgramEventType eventType;@Column(nullable=false,length=1000,updatable=false)private String reason;@Column(name="actor_employee_id",columnDefinition="uuid",updatable=false)private UUID actorEmployeeId;@JdbcTypeCode(SqlTypes.JSON)@Column(name="details_json",columnDefinition="jsonb",nullable=false,updatable=false)private String detailsJson;
 @PrePersist void prePersist(){if(id==null)id=UuidV7.generate();}public UUID getId(){return id;}public void setId(UUID v){id=v;}public UUID getProgramId(){return programId;}public void setProgramId(UUID v){programId=v;}public UUID getParticipantId(){return participantId;}public void setParticipantId(UUID v){participantId=v;}public ProgramEventType getEventType(){return eventType;}public void setEventType(ProgramEventType v){eventType=v;}public String getReason(){return reason;}public void setReason(String v){reason=v;}public UUID getActorEmployeeId(){return actorEmployeeId;}public void setActorEmployeeId(UUID v){actorEmployeeId=v;}public String getDetailsJson(){return detailsJson;}public void setDetailsJson(String v){detailsJson=v;}
}
